ies.append({ "ie_type" : "RAT Type", "ie_value" : "RAT Type", "presence" : "C", "instance" : "0", "comment" : "The RAT Type indicates the Radio Access Technology which is used in the new system. "})
ies.append({ "ie_type" : "Indication", "ie_value" : "Indication", "presence" : "CO", "instance" : "0", "comment" : "This IE shall be included if any one of the applicable flags is set to 1.Applicable Flags are:-	The MS Validated (MSV) flag, when set to 1, indicates that the new system has successfully authenticated the UE, or the new system has validated the integrity protection of the TAU request message. See NOTE 3.-	The ETHPDN flag, when set to 1, indicates that the target MME supports Ethernet PDN connection."})
ies.append({ "ie_type" : "Hop Counter", "ie_value" : "Hop Counter", "presence" : "O", "instance" : "0", "comment" : "If an SGSN within the same SGSN pool with the old SGSN receives this message, the SGSN shall decrement the Hop Counter if this IE is present in the received message; otherwise, the SGSN may include a Hop Counter with a value of max-1, and may relay the message to the old SGSN."})
ies.append({ "ie_type" : "Serving Network", "ie_value" : "Target PLMN ID", "presence" : "CO", "instance" : "0", "comment" : "If available, this IE shall be included in order to allow old MME/SGSN to make a judgment whether un-used authentication vectors to be distributed or not."})
ies.append({ "ie_type" : "LDN", "ie_value" : "MME/S4-SGSN LDN", "presence" : "O", "instance" : "0", "comment" : "This IE is optionally sent by the MME/S4-SGSN to the peer MME/S4-SGSN on the S3/S10/S16 interfaces (see TS32.423[44]), when communicating the LDN to the peer node for the first time."})
ies.append({ "ie_type" : "FQDN", "ie_value" : "SGSN node name", "presence" : "CO", "instance" : "0", "comment" : "This IE shall be sent by the new SGSN on the S3 interface if both new SGSN and associated SGW support ISR. See NOTE 2."})
