ies.append({ "ie_type" : "Node Identifier", "ie_value" : "SGSN Identifier", "presence" : "O", "instance" : "0", "comment" : "This IE may be sent by the target S4-SGSN to the source MME/S4-SGSN as specified in TS23.271[56]."})
