ies.append({ "ie_type" : "CIoT Optimizations Support Indication", "ie_value" : "CIoT Optimizations Support Indication", "presence" : "CO", "instance" : "0", "comment" : "This IE shall be sent by the new MME/SGSN on the S10/S3/S16/N26 interface if it supports at least one CIoT optimization.This IE shall be sent by the new AMF on the N26 interface, with the AWOPDN bit set to 1 and, if Unstructured or Ethernet PDU session types are supported, with the SGNIPDN bit set to 1."})
